import{c as t,Q as o,j as a,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Copilot — Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/privacy.md","filePath":"copilot/privacy.md","lastUpdated":null}'),i={name:"copilot/privacy.md"};function n(s,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="copilot-—-privacy" tabindex="-1">Copilot — Privacy <a class="header-anchor" href="#copilot-—-privacy" aria-label="Permalink to &quot;Copilot — Privacy&quot;">​</a></h1><p>The Copilot is useful only because it can see your money. Here is exactly what it sees and when.</p><h2 id="what-the-copilot-receives" tabindex="-1">What the Copilot receives <a class="header-anchor" href="#what-the-copilot-receives" aria-label="Permalink to &quot;What the Copilot receives&quot;">​</a></h2><p>At each Copilot question, <code>finsight-agent::context::build_context</code> assembles a <strong>FinancialContext</strong> scoped to the question:</p><ul><li>Cashflow (balances, run rate), Budget (envelopes, To Budget), Goals (targets, progress), windowed transactions, wellness metrics, currency and unconverted holdings, and investment positions as imported.</li></ul><p>No more is sent than the task needs. Auto-categorization sends even less — only the merchant description and amount of <em>uncategorized</em> transactions.</p><h2 id="provider-choice-matters" tabindex="-1">Provider choice matters <a class="header-anchor" href="#provider-choice-matters" aria-label="Permalink to &quot;Provider choice matters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Where inference runs</th><th>Data leaves your server?</th></tr></thead><tbody><tr><td><strong>Ollama</strong> (local)</td><td>Your machine / LAN</td><td>No — same context over your local network</td></tr><tr><td><strong>OpenAI-compatible</strong></td><td>Remote API you configured</td><td>Yes — the context for that question</td></tr><tr><td><strong>Anthropic</strong></td><td>Remote API you configured</td><td>Yes — the context for that question</td></tr></tbody></table><ul><li>Provider API keys and SimpleFIN URLs are stored <strong>per-user inside your encrypted <code>data.sqlcipher</code></strong>, not in a global server slot.</li><li>No provider is configured by default. Settings → Agent shows the data-flow explanation before you save.</li><li>Change or remove the provider at any time; local ledger data is untouched.</li></ul><h2 id="what-the-copilot-never-does" tabindex="-1">What the Copilot never does <a class="header-anchor" href="#what-the-copilot-never-does" aria-label="Permalink to &quot;What the Copilot never does&quot;">​</a></h2><ul><li>Store your ledger on a vendor’s servers.</li><li>Invent exchange rates for unconverted currencies — the <code>CurrencyContext</code> block forces disclosure.</li><li>Remember across users. Households share a server image but not a database — each user’s context is isolated.</li></ul><h2 id="offline-cache" tabindex="-1">Offline cache <a class="header-anchor" href="#offline-cache" aria-label="Permalink to &quot;Offline cache&quot;">​</a></h2><p>The browser’s seven-day IndexedDB cache is <strong>read-only, encrypted when the PWA has a secure context, and purged on logout</strong>. It is not the vault — <code>data.sqlcipher</code> is.</p><p>Questions about the overall encryption design belong on <a href="/FinSight/getting-started/privacy">Privacy &amp; Local Data</a> and <a href="/FinSight/help/security">Security &amp; Privacy</a>.</p>',14)])])}const v=t(i,[["render",n]]);export{u as __pageData,v as default};
